<div x-show="statusModalOpen" x-cloak class="fixed inset-0 z-[70] flex items-center justify-center bg-black/20 p-4" role="dialog" aria-modal="true"><div class="w-full max-w-md overflow-hidden rounded-xl bg-white shadow-2xl"><header class="flex items-start justify-between border-b border-slate-200 p-5"><div><p class="text-[10px] font-semibold uppercase tracking-wider text-gray-500">SENIOR RECORDS</p><h3 class="text-lg font-bold text-gray-900">Update Life / Health Status</h3></div><button type="button" @click="statusModalOpen = false" aria-label="Close status modal" class="text-gray-500"><svg class="h-6 w-6" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="space-y-2 p-5"><p class="mb-4 text-sm text-gray-500">Changing this status will affect payout eligibility and benefit scheduling for <b class="text-gray-900" x-text="selectedRecord.firstName + ' ' + selectedRecord.lastName"></b>.</p>@foreach ([['key'=>'active','label'=>'Active','color'=>'green'],['key'=>'bedridden','label'=>'Bedridden','color'=>'orange'],['key'=>'confined','label'=>'Confined','color'=>'purple'],['key'=>'relocated','label'=>'Relocated','color'=>'yellow'],['key'=>'deceased','label'=>'Deceased','color'=>'red']] as $item)<button type="button" @click.prevent="selectedStatus = '{{ $item['key'] }}'" :class="selectedStatus === '{{ $item['key'] }}' ? 'border-blue-300 bg-blue-50' : 'border-slate-200 bg-white'" class="flex w-full items-center justify-between rounded-xl border px-4 py-3 text-left"><span class="flex items-center gap-3 font-semibold"><span class="h-2.5 w-2.5 rounded-full bg-{{ $item['color'] }}-500"></span>{{ $item['label'] }}</span><svg x-show="selectedStatus === '{{ $item['key'] }}'" class="h-5 w-5 text-blue-600" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" stroke-linejoin="round" d="m5 12 4 4L19 6"/></svg></button>@endforeach</div><footer class="flex gap-2 border-t border-slate-200 p-4"><button type="button" @click="statusModalOpen = false" class="flex-1 rounded-xl border border-slate-200 py-3 font-semibold text-gray-700">Cancel</button><button type="button" @click="selectedRecord.status = selectedStatus.charAt(0).toUpperCase() + selectedStatus.slice(1); statusModalOpen = false" class="flex-1 rounded-xl bg-blue-600 py-3 font-semibold text-white">Save Status</button></footer></div></div>
